// "AI Sekarang Bisa Belanja Sendiri" — shot plan timed to voice/words.json.
// ALL timings come from timing.ts (generated by gen_timings.py). When the VO is
// re-recorded, re-run gen_timings.py and every boundary/event below moves with it.
// No frame number is hand-timed here: keys are computed from SHOT_BOUNDS.
//
// World layout (metres, floor y = 0):
//   room    — living room around the origin; couch at (0.6, 0, -2.6), Zaky sits there.
//   sky     — floating platform at (24, 8, 0); three rice-cooker cards + a cart.
//   street  — two houses at x -27 / -21, z -2 (golden ending); package vs waiting clock.
import { TOTAL as TOTAL_GEN, FPS as FPS_GEN, SHOT_BOUNDS, FLASH_AT as FLASH_GEN,
  DOTS_POP, WALLET_T, COMPARE_T, PICK_T, TAP_T, TOKEN_T, WAIT_T, CTA_T } from "./timing";

export const FPS = FPS_GEN;
export const TOTAL = TOTAL_GEN;
export const FLASH_AT = FLASH_GEN;
export const D0 = 0; // floor level (kept for build.ts's house() default)
export type V3 = [number, number, number];

export const clamp01 = (x: number) => Math.max(0, Math.min(1, x));
export const smooth = (x: number) => { const u = clamp01(x); return u * u * (3 - 2 * u); };
export const easeOut = (u: number) => 1 - (1 - clamp01(u)) ** 4;
export { DOTS_POP, WALLET_T, COMPARE_T, PICK_T, TAP_T, TOKEN_T, WAIT_T, CTA_T };

// ---------------- story physics (t = seconds) ----------------
/** Dots the robot-agent hovers: gentle bob, 0.9 Hz */
export const dotsBob = (t: number) => 0.09 * Math.sin(2 * Math.PI * 0.9 * t);
/** product cards bob out of phase */
export const cardBob = (t: number, i: number) => 0.12 * Math.sin(2 * Math.PI * 0.7 * t + i * 2.1);
/** the chosen cooker (middle card) flies into the cart over 0.55 s after PICK_T */
export const pickU = (t: number) => smooth((t - PICK_T) / 0.55);
/** the finger press: dips 0.15 s before TAP_T, back up 0.3 s after */
export const tapU = (t: number) => {
  if (t < TAP_T - 0.15 || t > TAP_T + 0.3) return 0;
  return t < TAP_T ? smooth((t - (TAP_T - 0.15)) / 0.15) : 1 - smooth((t - TAP_T) / 0.3);
};
/** the card flips into a gold token over 0.6 s after TOKEN_T */
export const tokenU = (t: number) => smooth((t - TOKEN_T) / 0.6);
/** the waiting clock pops in at WAIT_T with a little overshoot */
export const clockU = (t: number) => {
  const u = (t - WAIT_T) / 0.5;
  if (u <= 0) return 0;
  if (u >= 1) return 1;
  return easeOut(u) * (1 + 0.18 * Math.sin(u * Math.PI));
};

// ---------------- shots ----------------
export type Light = "day" | "golden";
export type Crowd = "room" | "sky" | "street" | "none";
export type ShotDef = { id: number; a: number; b: number; light: Light; crowd: Crowd };
export const SHOTS: ShotDef[] = SHOT_BOUNDS.map(([a, b], i) => ({
  id: i + 1, a, b,
  light: (i === 6 ? "golden" : "day") as Light,
  crowd: (["room", "room", "room", "sky", "room", "room", "street"] as Crowd[])[i],
}));
/** crossfades (frames) at place changes: room -> sky, sky -> room, room -> street */
export const XFADE: Record<number, number> = { 4: 8, 5: 8, 7: 10 };

export const shotAt = (f: number) => SHOTS.find((s) => f >= s.a && f < s.b) ?? SHOTS[SHOTS.length - 1];
export const layersAt = (f: number): { id: number; alpha: number }[] => {
  for (const s of SHOTS) {
    const x = XFADE[s.id];
    if (x && f >= s.a - x / 2 && f < s.a + x / 2) return [{ id: s.id - 1, alpha: 1 }, { id: s.id, alpha: (f - (s.a - x / 2) + 1) / (x + 1) }];
  }
  return [{ id: shotAt(f).id, alpha: 1 }];
};

// ---------------- camera ----------------
export type Cam = { pos: V3; look: V3; fov: number; roll: number };
type Shot = Partial<Cam> & { pos: V3; look: V3 };
type Key = { f: number; dur?: number; cut?: boolean; s: (f: number) => Shot };
export const glide = (u: number) => { const x = clamp01(u); return x * x * x * (x * (6 * x - 15) + 10); };
const mix = (a: Cam, b: Cam, k: number): Cam => ({
  pos: a.pos.map((v, i) => v + (b.pos[i] - v) * k) as V3, look: a.look.map((v, i) => v + (b.look[i] - v) * k) as V3,
  fov: a.fov + (b.fov - a.fov) * k, roll: a.roll + (b.roll - a.roll) * k,
});
const full = (c: Shot): Cam => ({ fov: 40, roll: 0, ...c });
const run = (keys: Key[], f: number) => {
  let cur = full(keys[0].s(f));
  for (let i = 1; i < keys.length; i++) {
    const k = keys[i];
    if (f < k.f) break;
    cur = k.cut ? full(k.s(f)) : mix(cur, full(k.s(f)), glide((f - k.f) / (k.dur ?? 24)));
  }
  return cur;
};
const pushK = (f: number, f0: number, rate: number, punch = 0, n = 35) => {
  const x = Math.max(0, f - f0);
  let s = rate * x;
  if (punch > rate) for (let i = 0; i < Math.min(x, n); i++) s += (punch - rate) * Math.max(0, Math.min(1, (i + 0.5) / 8, (n - i - 0.5) / 8));
  return Math.exp(-s);
};
const dolly = (pos: V3, look: V3, k: number, rest: Partial<Cam> = {}): Shot =>
  ({ pos: [look[0] + (pos[0] - look[0]) * k, look[1] + (pos[1] - look[1]) * k, look[2] + (pos[2] - look[2]) * k], look, ...rest });
const zoom = (pos: V3, look: V3, fov: number, k: number, rest: Partial<Cam> = {}): Shot =>
  ({ pos, look, fov: (360 / Math.PI) * Math.atan(Math.tan((fov * Math.PI) / 360) * k), ...rest });
const rolled = (s: (f: number) => Shot, roll: number) => (f: number): Shot => ({ ...s(f), roll });

// shot bounds in frames (from timing.ts)
const B = (i: number) => SHOT_BOUNDS[i - 1];
const F = (sec: number) => Math.round(sec * FPS);

// ---- framings ----
// shot 1 (hook CU): Zaky on the couch, phone in hand; Dots pops out of the phone at DOTS_POP
// Zaky sits at z=-2.1 (in front of the couch seat); keep the lens >= 2.3 m away or he overflows the frame
const S1a = (f: number) => dolly([0.6, 1.6, 2.2], [0.6, 1.3, -2.1], pushK(f, B(1)[0], 0.0025), { fov: 40 });
const S1b = (f: number) => dolly([0.5, 1.55, 1.4], [0.7, 1.35, -2.0], pushK(f, F(DOTS_POP), 0.002, 0.006, 30), { fov: 38, roll: -0.03 });
// shot 2 (wide living room): Zaky gestures, "kedengarannya kayak film"
const S2a = (f: number) => dolly([3.9, 2.3, 3.4], [0, 1.2, -2.6], pushK(f, B(2)[0], 0.0016), { fov: 44 });
const S2b = (f: number) => dolly([3.1, 2.0, 2.6], [0.3, 1.3, -2.6], pushK(f, B(2)[0] + 40, 0.0018), { fov: 42, roll: 0.02 });
// shot 3 (wallet CU): Dots floats in front of Zaky holding the wallet
const S3a = (f: number) => dolly([0.6, 1.8, 2.0], [0.65, 1.45, -1.4], pushK(f, B(3)[0], 0.0022), { fov: 38 });
const S3b = (f: number) => dolly([0.35, 1.75, 1.6], [0.7, 1.45, -1.4], pushK(f, F(WALLET_T), 0.002, 0.005, 30), { fov: 36, roll: 0.03 });
// shot 4 (digital sky): zoom in to phone during voice chat -> 3 rice cookers comparison -> pick to cart
const S4a = (f: number) => dolly([24, 10.3, 10.8], [24, 10.0, 7.2], pushK(f, B(4)[0], 0.0018), { fov: 32 });
const S4b = (f: number) => dolly([22.6, 10.2, 4.6], [24, 9.8, -1.2], pushK(f, F(COMPARE_T), 0.002), { fov: 38, roll: -0.03 });
const S4c = (f: number) => dolly([26.5, 9.6, 6.5], [24, 9.0, 0.8], pushK(f, F(PICK_T), 0.0022, 0.005, 28), { fov: 36, roll: 0.03 });
// shot 5 (phone approval CU): big phone, fingerprint, finger taps at TAP_T
const S5a = (f: number) => dolly([0.6, 1.55, 0.9], [0.6, 1.5, -1.2], pushK(f, B(5)[0], 0.002), { fov: 30 });
const S5b = (f: number) => dolly([0.6, 1.5, 0.35], [0.6, 1.5, -1.2], pushK(f, F(TAP_T), 0.0018, 0.006, 24), { fov: 28 });
// shot 6 (token): Zaky holding the card, flips into gold token with security relayer
const S6a = (f: number) => dolly([2.2, 1.7, 0.6], [0.6, 1.35, -1.5], pushK(f, B(6)[0], 0.0018), { fov: 36, roll: -0.02 });
const S6b = (f: number) => dolly([2.0, 1.6, 0.2], [0.6, 1.35, -1.5], pushK(f, F(TOKEN_T), 0.002, 0.005, 28), { fov: 34, roll: 0.02 });
// shot 7 (golden street): two houses span 11.5 m, so the wide sits ~22 m back;
// the clock floats at y 3.8 so it stays in frame on the closer shot
const S7a = (f: number) => dolly([-24, 4.5, 20], [-24, 2, -2], pushK(f, B(7)[0], 0.0012), { fov: 50 });
const S7b = (f: number) => dolly([-23.2, 2.8, 7.0], [-20.2, 1.8, 1.8], pushK(f, F(WAIT_T), 0.0015), { fov: 40, roll: 0.02 });
const S7c = (f: number) => {
  const s = glide((f - (B(7)[1] - 90)) / 90);
  return { pos: [-24 + 6 * s, 4.5 + 6.5 * s, 14 + 8 * s] as V3, look: [-24, 2 + 1.5 * s, -2] as V3, fov: 48 - 4 * s, roll: 0 };
};

const CAMS: Record<number, Key[]> = {
  1: [
    { f: B(1)[0], s: S1a },
    { f: F(DOTS_POP), dur: 30, s: S1b },
  ],
  2: [
    { f: B(2)[0], s: S2a },
    { f: B(2)[0] + 40, dur: 30, s: S2b },
  ],
  3: [
    { f: B(3)[0], s: S3a },
    { f: F(WALLET_T), dur: 28, s: S3b },
  ],
  4: [
    { f: B(4)[0], s: S4a },
    { f: F(COMPARE_T), dur: 30, s: S4b },
    { f: F(PICK_T), dur: 26, s: S4c },
  ],
  5: [
    { f: B(5)[0], s: S5a },
    { f: F(TAP_T), dur: 24, s: S5b },
  ],
  6: [
    { f: B(6)[0], s: S6a },
    { f: F(TOKEN_T), dur: 26, s: S6b },
  ],
  7: [
    { f: B(7)[0], s: S7a },
    { f: F(WAIT_T), dur: 30, s: S7b },
    { f: B(7)[1] - 90, cut: true, s: S7c },
  ],
};

// impact kicks: the pick lands in the cart, the finger taps, the token flips (7 f, flip sign each frame)
const KICKS: [number, number][] = [[PICK_T, 0.8], [TAP_T, 1.0], [TOKEN_T, 0.7]];
export const kickAt = (t: number) => {
  let a = 0;
  for (const [t0, g] of KICKS) {
    const n = Math.floor((t - t0) * FPS + 1e-6);
    if (n >= 0 && n < 7) a += g * (n % 2 ? -1 : 1) * (1 - n / 7) ** 1.5;
  }
  return a;
};
export const camAt = (id: number, f: number): Cam => {
  const c = run(CAMS[id], f), a = kickAt(f / FPS);
  if (!a) return c;
  const d: V3 = [c.look[0] - c.pos[0], c.look[1] - c.pos[1], c.look[2] - c.pos[2]];
  const L = Math.hypot(...d), h = Math.hypot(d[0], d[2]) || 1;
  const m = (3 / 640) * Math.tan((c.fov * Math.PI) / 360) * L * a;
  return { ...c, look: [c.look[0] - (d[2] / h) * m, c.look[1] + 0.6 * m, c.look[2] + (d[0] / h) * m], roll: c.roll + a * 0.004 };
};
export const keyEnd = (id: number, f: number) => {
  let e = 0;
  for (const k of CAMS[id]) if (f >= k.f) e = k.f + (k.cut ? 0 : k.dur ?? 24);
  return Math.max(f, e);
};

// ---------------- lens: depth of field ----------------
export type Dof = { f: number; dur?: number; cInf: number; focus?: (f: number) => V3 };
const ZAKY_EYES: V3 = [0.6, 1.45, -2.6];
const DOTS_POS: V3 = [0.6, 1.6, -1.5];
const CARDS_POS: V3 = [24, 9.8, -1.2];
const PHONE_POS: V3 = [0.6, 1.5, -1.2];
export const DOF: Dof[] = [
  { f: B(1)[0], cInf: 14, focus: () => ZAKY_EYES },   // hook CU: Zaky sharp, room soft
  { f: B(2)[0], cInf: 0 },                            // wide room: everything sharp
  { f: B(3)[0], cInf: 12, focus: () => DOTS_POS },    // wallet CU: Dots sharp
  { f: B(4)[0], cInf: 0 },                            // sky wide: sharp
  { f: F(COMPARE_T), dur: 30, cInf: 10, focus: () => CARDS_POS }, // cards close: cards sharp
  { f: B(5)[0], cInf: 8, focus: () => PHONE_POS },    // phone CU: mild, screen sharp
  { f: B(6)[0], cInf: 10, focus: () => PHONE_POS },   // token: token sharp
  { f: B(7)[0], cInf: 0 },                            // street wide: sharp
  { f: F(WAIT_T), dur: 30, cInf: 7, focus: () => [-21.5, 1.4, -1] }, // Zaky waiting: mild
];
export const dofAt = (f: number) => {
  let i = 0; while (i + 1 < DOF.length && f >= DOF[i + 1].f) i++;
  const d = DOF[i], p = DOF[Math.max(0, i - 1)];
  const k = d.dur ? Math.min(1, (f - d.f) / d.dur) : 1;
  return { cInf: p.cInf + (d.cInf - p.cInf) * k, focus: d.focus };
};
export const focusAt = (id: number, f: number): V3 => {
  const d = dofAt(f);
  return d.focus ? d.focus(f) : camAt(id, f).look;
};

// ---------------- foreground framing ----------------
export type Fg = { a: number; b: number; kit: string; pos: V3; s?: number; yaw?: number };
export const FOREGROUND: Fg[] = [
  // wide room (shot 2): a plant in the bottom-left corner — built from primitives in world.ts, not the Kenney kit
  { a: B(2)[0], b: B(2)[1], kit: "plant", pos: [-3.6, 0, 2.6], s: 1.4, yaw: 0.3 },
];
